package com.smartmanager.nativeapp;
import android.content.*;
/** Local non-sensitive template preferences; card secrets remain encrypted in batch storage. */
public final class TemplateStore {private final SharedPreferences p;public TemplateStore(Context c){p=c.getSharedPreferences("card_templates",Context.MODE_PRIVATE);}public CardTemplate get(){return new CardTemplate("default",p.getString("name","Smart Manager A4"),p.getInt("w",595),p.getInt("h",842),p.getInt("rows",6),p.getInt("columns",2),p.getInt("margin",26),p.getInt("gap",9),p.getBoolean("user",true),p.getBoolean("password",true),p.getBoolean("profile",true),p.getBoolean("serial",true));}public boolean save(CardTemplate t){return p.edit().putString("name",t.name).putInt("w",t.paperW).putInt("h",t.paperH).putInt("rows",t.rows).putInt("columns",t.columns).putInt("margin",t.margin).putInt("gap",t.gap).putBoolean("user",t.showUser).putBoolean("password",t.showPassword).putBoolean("profile",t.showProfile).putBoolean("serial",t.showSerial).commit();}}
